 function limit(value,fallback,maximum){const n=Number(value===undefined?fallback:value);if(!Number.isInteger(n)||n<1||n>maximum)throw Error('Invalid usage limit');return n;}
 const daily=limit(env.DAILY_REQUEST_LIMIT,10,100),monthly=limit(env.MONTHLY_REQUEST_LIMIT,100,1000);
